// Validates the rules generated by `mergePerms` against the real Instant server (test app).
import { afterAll, beforeAll, describe, expect, setDefaultTimeout, test } from "bun:test";
import { id } from "@instantdb/admin";
import { adminIC, criarGrupo, limpar, limparRestos, novoPrefixo, novoUsuario } from "../helpers";

setDefaultTimeout(30_000);

const PREFIXO = novoPrefixo("regras");
const admin = adminIC();

type Usuario = Awaited<ReturnType<typeof novoUsuario>>;

async function erroDe(p: Promise<unknown>): Promise<unknown> {
  try {
    await p;
  } catch (e) {
    return e;
  }
  throw new Error("expected an error, but the operation succeeded");
}

function tipoErro(e: unknown): string | undefined {
  return (e as { body?: { type?: string } })?.body?.type;
}

async function esperarNegado(p: Promise<unknown>) {
  expect(tipoErro(await erroDe(p))).toBe("permission-denied");
}

function criarSorteio(u: Usuario, grupoId: string, sorteioId = id(), extra: Record<string, unknown> = {}) {
  return u.db.transact(
    u.db.tx.sorteios[sorteioId]!
      .create({ status: "pending", attempts: 0, createdAt: Date.now(), rodada: 1, chave: `${grupoId}:${sorteioId}`, ...extra })
      .link({ grupo: grupoId }),
  );
}

async function sorteiosDe(grupoId: string) {
  const r = await admin.query({ sorteios: { $: { where: { "grupo.id": grupoId } }, grupo: {} } });
  return r.sorteios;
}

beforeAll(limparRestos);
afterAll(() => limpar(PREFIXO));

describe("generated rules", () => {
  test("organizer creates a pending command linked to their group", async () => {
    const org = await novoUsuario(PREFIXO);
    const grupoId = await criarGrupo(PREFIXO, org);
    const sorteioId = id();
    await criarSorteio(org, grupoId, sorteioId);
    const [s] = await sorteiosDe(grupoId);
    expect(s!.id).toBe(sorteioId);
    expect(s!.status).toBe("pending");
    expect(s!.grupo?.id).toBe(grupoId);
    const visto = await org.db.query({ sorteios: { $: { where: { id: sorteioId } } } });
    expect(visto.sorteios.map((x) => x.id)).toEqual([sorteioId]);
  });

  test("cannot create with status other than pending or attempts != 0", async () => {
    const org = await novoUsuario(PREFIXO);
    const grupoId = await criarGrupo(PREFIXO, org);
    await esperarNegado(criarSorteio(org, grupoId, id(), { status: "done" }));
    await esperarNegado(criarSorteio(org, grupoId, id(), { attempts: 1 }));
    expect(await sorteiosDe(grupoId)).toEqual([]);
  });

  test("cannot create with rodada 0", async () => {
    const org = await novoUsuario(PREFIXO);
    const grupoId = await criarGrupo(PREFIXO, org);
    await esperarNegado(criarSorteio(org, grupoId, id(), { rodada: 0 }));
    expect(await sorteiosDe(grupoId)).toEqual([]);
  });

  test("non-organizer cannot create", async () => {
    const org = await novoUsuario(PREFIXO);
    const outro = await novoUsuario(PREFIXO);
    const grupoId = await criarGrupo(PREFIXO, org);
    await esperarNegado(criarSorteio(outro, grupoId));
    expect(await sorteiosDe(grupoId)).toEqual([]);
  });

  test("client cannot update status", async () => {
    const org = await novoUsuario(PREFIXO);
    const grupoId = await criarGrupo(PREFIXO, org);
    const sorteioId = id();
    await criarSorteio(org, grupoId, sorteioId);
    await esperarNegado(org.db.transact(org.db.tx.sorteios[sorteioId]!.update({ status: "done" })));
    const [s] = await sorteiosDe(grupoId);
    expect(s!.status).toBe("pending");
  });

  test("client cannot unlink the command from the group", async () => {
    const org = await novoUsuario(PREFIXO);
    const grupoId = await criarGrupo(PREFIXO, org);
    const sorteioId = id();
    await criarSorteio(org, grupoId, sorteioId);
    await esperarNegado(org.db.transact(org.db.tx.sorteios[sorteioId]!.unlink({ grupo: grupoId })));
    await esperarNegado(org.db.transact(org.db.tx.grupos[grupoId]!.unlink({ sorteios: sorteioId })));
    const [s] = await sorteiosDe(grupoId);
    expect(s!.grupo?.id).toBe(grupoId);
  });

  test("organizer can delete the group and the commands cascade", async () => {
    const org = await novoUsuario(PREFIXO);
    const grupoId = await criarGrupo(PREFIXO, org);
    const sorteioId = id();
    await criarSorteio(org, grupoId, sorteioId);
    await org.db.transact(org.db.tx.grupos[grupoId]!.delete());
    const r = await admin.query({
      grupos: { $: { where: { id: grupoId } } },
      sorteios: { $: { where: { id: sorteioId } } },
    });
    expect(r.grupos).toEqual([]);
    expect(r.sorteios).toEqual([]);
  });

  test("rate limit: the 6th create in the hour is refused", async () => {
    const org = await novoUsuario(PREFIXO);
    const grupoId = await criarGrupo(PREFIXO, org);
    for (let n = 0; n < 5; n++) await criarSorteio(org, grupoId);
    expect(tipoErro(await erroDe(criarSorteio(org, grupoId)))).toBe("rate-limited");
    expect(await sorteiosDe(grupoId)).toHaveLength(5);
  });
});
